import React from 'react';

const Icon = ({ path, className = 'icon' }) => (
  // CORREÇÃO: Removido fill="currentColor". A cor será controlada 100% pelo CSS.
  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" className={className}>
    <path d={path} />
  </svg>
);

export default Icon;
